/*
  Hand-made pixel art for Palabritas (battle sprites), as rows of characters: each character
  is a color from the sprite's palette, '.' is transparent. Front = how the opponent looks,
  back = your own Palabrita, seen from behind. Canvas up to 56x56 (Gen 2's size), content up to
  54 px tall so it clears the health boxes.
  Palabritas not listed here are drawn from shapes in art/creatures.ts.

  Sources (made with ChatGPT, real 56x56 pixels in the master palette unless noted):
  art-src/creature_front_small.png + creature_back_small.png (Aguacatito, small; eyes and mouth redrawn by hand),
  art-src/lizard_front.png + lizard_back.png (Brasita, not in the game yet),
  art-src/shark_front.png + shark_back.png (Mordisquito, not in the game yet),
  art-src/wood_pigeon_front_56x56.png + wood_pigeon_back_56x56.png (Palomón; colors grouped, made before the palette),
  art-src/Salchichita_front.png + Salchichita_back.png,
  and the 8x sheets art-src/<name>_front_8x.png + <name>_back_8x.png (shrunk with tools/unscale.mjs, K=16):
  pajarito, conejito, liebron, gogita (gotita), nubarron, tornado (huracan), aguacatono, final_stage_avocado (aguacatero), hamburgueson, nacatamal_dog (nacatamastin), gusanito, capullito, mariposita, hojarasco, cojincito, sillon, ochopatas, taranton, cuernito, herculeo, ardillita, ardillon, brasaurio, cangrejito, cangrejon, caparazonte, cocotero, colibri, coquito, ecolin, espinita, gliptodon, guardabarranco, hormigon, hormiguita, maleticano, mojarrita, mordiscon, murcielon, ollita, paslamita, paslamona, pelicanito, petroglifon, piedrita, puercoespin, tinajon, volcasaurio, zumbador (and new versions of brasita), chispita, coheton, chocoyito, chocoyote, zopilotito, zopiloton, venadito, torovenado, perezosito, lamparita,  (and new versions of aguacatito),  (and new versions of aguacatero), tilapita, espadon.
*/
